export interface HostRunRunnerRuntime {
  spawnChild?: (command: string, argv: string[], options: {
    cwd: string;
    env: NodeJS.ProcessEnv;
    stdio: ['pipe', 'pipe', 'pipe'] | ['pipe', 'pipe', 'pipe', 'pipe'];
