  const path = normalizeReadLogPath(rawPathFromEvent(record), context, 'read event.path');
  if (!isDecisionMarkdownPath(path, context)) return null;
  return {
    path,
    mode: readModeFromEvent(record),
    tokenCount: tokenCountFromEvent(record),
    agent: context.agent!,
